steps.run:
set -euo pipefail
command -v taskset >/dev/null 2>&1 || {
  echo "::error::taskset absent — the 2-vCPU budget cannot be enforced on this host"; exit 1; }
[ "$(nproc)" -ge 2 ] || {
  echo "::error::host reports $(nproc) CPU(s); the 2-vCPU budget shape does not apply"; exit 1; }
allowed="$(awk '/^Cpus_allowed_list:/{print $2}' /proc/self/status)"
cpus="$(printf '%s\n' "$allowed" | tr ',' '\n' | while read -r r; do
          [ -n "$r" ] || continue
          case "$r" in *-*) seq "${r%-*}" "${r#*-}" ;; *) printf '%s\n' "$r" ;; esac
        done | head -2 | paste -sd, -)"
[ "$(printf '%s\n' "$cpus" | tr ',' '\n' | grep -c .)" = "2" ] || {
  echo "::error::could not select 2 CPUs from the allowed set '$allowed'"; exit 1; }
budget="$(taskset -c "$cpus" nproc)"
[ "$budget" = "2" ] || {
  echo "::error::CPU budget NOT in effect (taskset -c $cpus nproc reported $budget, expected 2)"; exit 1; }
echo "CPU budget verified in effect: CPUs [$cpus] of allowed set [$allowed] ($(nproc) visible)"
taskset -c "$cpus" pnpm vitest run --project integration --disable-console-intercept
